static void ini(mpfr_t x){mpfr_init2(x,PREC);} static void zero(mpfr_t x){mpfr_set_ui(x,0,MPFR_RNDN);} static void setd(mpfr_t x,const char*s,mpfr_rnd_t r){mpfr_set_str(x,s,10,r);} static void neg(mpfr_t r,mpfr_t a,mpfr_rnd_t rnd){mpfr_t z;ini(z);zero(z);mpfr_sub(r,z,a,rnd);mpfr_clear(z);} static void set_rat(mpfr_t x,unsigned long num,unsigned long den,mpfr_rnd_t rnd){mpfr_t a,b;ini(a);ini(b);mpfr_set_ui(a,num,MPFR_RNDN);mpfr_set_ui(b,den,MPFR_RNDN);mpfr_div(x,a,b,rnd);mpfr_clear(a);mpfr_clear(b);}
static mpfr_t lnlo[K+1],lnhi[K+1];
static void init_logs(void){for(int n=0;n<=K;n++){ini(lnlo[n]);ini(lnhi[n]);if(n>=2){mpfr_t a;ini(a);mpfr_set_ui(a,n,MPFR_RNDN);mpfr_log(lnlo[n],a,MPFR_RNDD);mpfr_log(lnhi[n],a,MPFR_RNDU);mpfr_clear(a);}}}
static void clear_logs(void){for(int n=0;n<=K;n++){mpfr_clear(lnlo[n]);mpfr_clear(lnhi[n]);}}
static void exprel_up(mpfr_t out,mpfr_t z){mpfr_t eps,neps,tmp,num,den,one;ini(eps);ini(neps);ini(tmp);ini(num);ini(den);ini(one);setd(eps,"0.001",MPFR_RNDN);neg(neps,eps,MPFR_RNDN);mpfr_set_ui(one,1,MPFR_RNDN);if(mpfr_cmp(z,eps)<=0&&mpfr_cmp(z,neps)>=0){mpfr_exp(out,eps,MPFR_RNDU);}else if(mpfr_cmp_ui(z,0)>0){mpfr_expm1(num,z,MPFR_RNDU);mpfr_div(out,num,z,MPFR_RNDU);}else{mpfr_exp(tmp,z,MPFR_RNDD);mpfr_sub(num,one,tmp,MPFR_RNDU);neg(den,z,MPFR_RNDN);mpfr_div(out,num,den,MPFR_RNDU);}mpfr_clear(eps);mpfr_clear(neps);mpfr_clear(tmp);mpfr_clear(num);mpfr_clear(den);mpfr_clear(one);}
static void theta_up(mpfr_t out,mpfr_t z){mpfr_t eps,neps,one,tmp,tmp2,num,den,a;ini(eps);ini(neps);ini(one);ini(tmp);ini(tmp2);ini(num);ini(den);ini(a);setd(eps,"0.001",MPFR_RNDN);neg(neps,eps,MPFR_RNDN);mpfr_set_ui(one,1,MPFR_RNDN);if(mpfr_cmp(z,eps)<=0&&mpfr_cmp(z,neps)>=0){mpfr_exp(tmp,eps,MPFR_RNDU);setd(tmp2,"0.5",MPFR_RNDU);mpfr_mul(out,tmp,tmp2,MPFR_RNDU);}else if(mpfr_cmp_ui(z,0)>0){if(mpfr_cmp(z,one)<0){mpfr_sub(tmp,one,z,MPFR_RNDD);mpfr_exp(tmp2,z,MPFR_RNDD);mpfr_mul(tmp,tmp,tmp2,MPFR_RNDD);mpfr_sub(num,one,tmp,MPFR_RNDU);}else{mpfr_sub(tmp,z,one,MPFR_RNDU);mpfr_exp(tmp2,z,MPFR_RNDU);mpfr_mul(tmp,tmp,tmp2,MPFR_RNDU);mpfr_add_ui(num,tmp,1,MPFR_RNDU);}mpfr_sqr(den,z,MPFR_RNDD);mpfr_div(out,num,den,MPFR_RNDU);}else{neg(a,z,MPFR_RNDN);mpfr_add_ui(tmp,a,1,MPFR_RNDD);mpfr_exp(tmp2,z,MPFR_RNDD);mpfr_mul(tmp,tmp,tmp2,MPFR_RNDD);mpfr_sub(num,one,tmp,MPFR_RNDU);mpfr_sqr(den,a,MPFR_RNDD);mpfr_div(out,num,den,MPFR_RNDU);}mpfr_clear(eps);mpfr_clear(neps);mpfr_clear(one);mpfr_clear(tmp);mpfr_clear(tmp2);mpfr_clear(num);mpfr_clear(den);mpfr_clear(a);}
static void g1_upper(mpfr_t out,mpfr_t v,mpfr_t tb,mpfr_t c){mpfr_t a,b,four;ini(a);ini(b);ini(four);mpfr_set_ui(four,4,MPFR_RNDN);mpfr_sqr(a,v,MPFR_RNDU);mpfr_mul(a,a,tb,MPFR_RNDU);mpfr_div(a,a,four,MPFR_RNDU);mpfr_mul(b,c,v,MPFR_RNDD);mpfr_sub(out,a,b,MPFR_RNDU);mpfr_clear(a);mpfr_clear(b);mpfr_clear(four);}
static void chord_integrals(mpfr_t I0,mpfr_t I1,mpfr_t a,mpfr_t b,mpfr_t gA,mpfr_t gB){mpfr_t D,delta,exr,th,eg,tmp,tmp2;ini(D);ini(delta);ini(exr);ini(th);ini(eg);ini(tmp);ini(tmp2);mpfr_sub(D,b,a,MPFR_RNDU);mpfr_sub(delta,gB,gA,MPFR_RNDU);exprel_up(exr,delta);theta_up(th,delta);mpfr_exp(eg,gA,MPFR_RNDU);mpfr_mul(tmp,D,eg,MPFR_RNDU);mpfr_mul(I0,tmp,exr,MPFR_RNDU);mpfr_mul(tmp,a,D,MPFR_RNDU);mpfr_mul(tmp,tmp,exr,MPFR_RNDU);mpfr_sqr(tmp2,D,MPFR_RNDU);mpfr_mul(tmp2,tmp2,th,MPFR_RNDU);mpfr_add(tmp,tmp,tmp2,MPFR_RNDU);mpfr_mul(I1,eg,tmp,MPFR_RNDU);mpfr_clear(D);mpfr_clear(delta);mpfr_clear(exr);mpfr_clear(th);mpfr_clear(eg);mpfr_clear(tmp);mpfr_clear(tmp2);}
static void exp_tail_segment(mpfr_t I0,mpfr_t I1,mpfr_t a,mpfr_t b,mpfr_t rate){mpfr_t inv,inv2,ra,rb,eaU,ebL,Ta,Tb,tmp;ini(inv);ini(inv2);ini(ra);ini(rb);ini(eaU);ini(ebL);ini(Ta);ini(Tb);ini(tmp);mpfr_set_ui(tmp,1,MPFR_RNDN);mpfr_div(inv,tmp,rate,MPFR_RNDU);mpfr_sqr(inv2,inv,MPFR_RNDU);mpfr_mul(ra,rate,a,MPFR_RNDD);neg(ra,ra,MPFR_RNDU);mpfr_exp(eaU,ra,MPFR_RNDU);mpfr_mul(rb,rate,b,MPFR_RNDU);neg(rb,rb,MPFR_RNDD);mpfr_exp(ebL,rb,MPFR_RNDD);mpfr_sub(tmp,eaU,ebL,MPFR_RNDU);mpfr_mul(I0,tmp,inv,MPFR_RNDU);mpfr_mul(Ta,a,inv,MPFR_RNDU);mpfr_add(Ta,Ta,inv2,MPFR_RNDU);mpfr_mul(Ta,Ta,eaU,MPFR_RNDU);{mpfr_t invL,inv2L;ini(invL);ini(inv2L);mpfr_set_ui(tmp,1,MPFR_RNDN);mpfr_div(invL,tmp,rate,MPFR_RNDD);mpfr_sqr(inv2L,invL,MPFR_RNDD);mpfr_mul(Tb,b,invL,MPFR_RNDD);mpfr_add(Tb,Tb,inv2L,MPFR_RNDD);mpfr_mul(Tb,Tb,ebL,MPFR_RNDD);mpfr_clear(invL);mpfr_clear(inv2L);}mpfr_sub(I1,Ta,Tb,MPFR_RNDU);mpfr_clear(inv);mpfr_clear(inv2);mpfr_clear(ra);mpfr_clear(rb);mpfr_clear(eaU);mpfr_clear(ebL);mpfr_clear(Ta);mpfr_clear(Tb);mpfr_clear(tmp);}
static void tbox(int i,mpfr_t ta,mpfr_t tb){if(i<45){set_rat(ta,i,100,MPFR_RNDD);set_rat(tb,i+1,100,MPFR_RNDU);}else if(i<65){int k=i-45;set_rat(ta,450+2*k,1000,MPFR_RNDD);set_rat(tb,452+2*k,1000,MPFR_RNDU);}else if(i<83){int k=i-65;set_rat(ta,980+k,2000,MPFR_RNDD);set_rat(tb,981+k,2000,MPFR_RNDU);}else if(i<101){int k=i-83;set_rat(ta,9980+k,20000,MPFR_RNDD);set_rat(tb,9981+k,20000,MPFR_RNDU);}else{int k=i-101;set_rat(ta,99980+k,200000,MPFR_RNDD);set_rat(tb,99981+k,200000,MPFR_RNDU);}}
static double tlo(int i){if(i<45)return i/100.;if(i<65)return(450+2*(i-45))/1000.;if(i<83)return(980+i-65)/2000.;if(i<101)return(9980+i-83)/20000.;return(99980+i-101)/200000.;}static double thi(int i){if(i<45)return(i+1)/100.;if(i<65)return(452+2*(i-45))/1000.;if(i<83)return(981+i-65)/2000.;if(i<101)return(9981+i-83)/20000.;return(99981+i-101)/200000.;}
static int eval_box(int ti,int lj,mpfr_t margin,mpfr_t A0,mpfr_t A1){mpfr_t ta,tb,la,lb,eps,del,eta,phead,pI,cI,q,rate,r,u1,u2,u3,gA,gB,H0,H1,T0,T1,tmp,tmp2,w,I0,I1,Phi,S0,E0,E1,d,half,rad,Y,lhs,one,two,four;mpfr_t *v[]={&ta,&tb,&la,&lb,&eps,&del,&eta,&phead,&pI,&cI,&q,&rate,&r,&u1,&u2,&u3,&gA,&gB,&H0,&H1,&T0,&T1,&tmp,&tmp2,&w,&I0,&I1,&Phi,&S0,&E0,&E1,&d,&half,&rad,&Y,&lhs,&one,&two,&four};for(size_t i=0;i<sizeof(v)/sizeof(v[0]);i++)ini(*v[i]);mpfr_set_ui(one,1,MPFR_RNDN);mpfr_set_ui(two,2,MPFR_RNDN);mpfr_set_ui(four,4,MPFR_RNDN);tbox(ti,ta,tb);set_rat(la,140780+lj,20000,MPFR_RNDD);set_rat(lb,140781+lj,20000,MPFR_RNDU);setd(eps,"0.0000000001",MPFR_RNDU);setd(del,"0.000002",MPFR_RNDU);setd(phead,"0.5",MPFR_RNDD);mpfr_div(tmp,la,four,MPFR_RNDD);mpfr_add(phead,phead,tmp,MPFR_RNDD);mpfr_sub(phead,phead,eps,MPFR_RNDD);mpfr_div(eta,del,four,MPFR_RNDU);mpfr_add(eta,eta,eps,MPFR_RNDU);setd(pI,"0.5",MPFR_RNDD);mpfr_div(tmp,la,four,MPFR_RNDD);mpfr_add(pI,pI,tmp,MPFR_RNDD);mpfr_sub(pI,pI,eta,MPFR_RNDD);mpfr_sub(cI,pI,one,MPFR_RNDD);setd(q,"0.5",MPFR_RNDD);mpfr_set_ui(tmp,8,MPFR_RNDN);mpfr_div(tmp,la,tmp,MPFR_RNDD);mpfr_add(q,q,tmp,MPFR_RNDD);mpfr_sub(q,q,eta,MPFR_RNDD);mpfr_sub(rate,q,one,MPFR_RNDD);zero(H0);zero(H1);for(int n=2;n<=K;n++){mpfr_sqr(tmp,lnhi[n],MPFR_RNDU);mpfr_mul(tmp,tmp,tb,MPFR_RNDU);mpfr_div(tmp,tmp,four,MPFR_RNDU);mpfr_mul(tmp2,phead,lnlo[n],MPFR_RNDD);mpfr_sub(tmp,tmp,tmp2,MPFR_RNDU);mpfr_exp(w,tmp,MPFR_RNDU);mpfr_add(H0,H0,w,MPFR_RNDU);mpfr_mul(tmp,w,lnhi[n],MPFR_RNDU);mpfr_add(H1,H1,tmp,MPFR_RNDU);}mpfr_set_ui(tmp,K,MPFR_RNDN);mpfr_log(r,tmp,MPFR_RNDD);{mpfr_t laU,tbL;ini(laU);ini(tbL);set_rat(laU,140780+lj,20000,MPFR_RNDU);tbox(ti,tmp,tbL);mpfr_mul(tmp,two,tbL,MPFR_RNDD);mpfr_div(u1,laU,tmp,MPFR_RNDU);mpfr_clear(laU);mpfr_clear(tbL);}g1_upper(gA,r,tb,cI);g1_upper(gB,u1,tb,cI);chord_integrals(I0,I1,r,u1,gA,gB);mpfr_add(T0,H0,I0,MPFR_RNDU);mpfr_add(T1,H1,I1,MPFR_RNDU);if(ti==0){mpfr_t ea,inv,inv2;ini(ea);ini(inv);ini(inv2);mpfr_mul(tmp,rate,u1,MPFR_RNDD);neg(tmp,tmp,MPFR_RNDU);mpfr_exp(ea,tmp,MPFR_RNDU);mpfr_div(inv,one,rate,MPFR_RNDU);mpfr_sqr(inv2,inv,MPFR_RNDU);mpfr_mul(tmp,ea,inv,MPFR_RNDU);mpfr_add(T0,T0,tmp,MPFR_RNDU);mpfr_mul(tmp,u1,inv,MPFR_RNDU);mpfr_add(tmp,tmp,inv2,MPFR_RNDU);mpfr_mul(tmp,tmp,ea,MPFR_RNDU);mpfr_add(T1,T1,tmp,MPFR_RNDU);mpfr_clear(ea);mpfr_clear(inv);mpfr_clear(inv2);}else{mpfr_t laU;ini(laU);set_rat(laU,140780+lj,20000,MPFR_RNDU);mpfr_mul(tmp,two,ta,MPFR_RNDD);mpfr_div(u2,laU,tmp,MPFR_RNDU);exp_tail_segment(I0,I1,u1,u2,rate);mpfr_add(T0,T0,I0,MPFR_RNDU);mpfr_add(T1,T1,I1,MPFR_RNDU);mpfr_add(tmp,lb,del,MPFR_RNDU);mpfr_mul(tmp2,two,ta,MPFR_RNDD);mpfr_div(u3,tmp,tmp2,MPFR_RNDU);if(mpfr_cmp(u3,u2)>0){mpfr_t Dseg,g2,eg;ini(Dseg);ini(g2);ini(eg);mpfr_sub(Dseg,u3,u2,MPFR_RNDU);setd(tmp,"0.5",MPFR_RNDU);mpfr_add(tmp,tmp,eta,MPFR_RNDU);mpfr_mul(tmp,tmp,u2,MPFR_RNDU);mpfr_sqr(tmp2,u2,MPFR_RNDU);mpfr_mul(tmp2,tmp2,ta,MPFR_RNDD);mpfr_div(tmp2,tmp2,four,MPFR_RNDD);mpfr_sub(g2,tmp,tmp2,MPFR_RNDU);mpfr_exp(eg,g2,MPFR_RNDU);mpfr_mul(I0,eg,Dseg,MPFR_RNDU);mpfr_add(T0,T0,I0,MPFR_RNDU);mpfr_mul(tmp,u2,Dseg,MPFR_RNDU);mpfr_sqr(tmp2,Dseg,MPFR_RNDU);mpfr_div(tmp2,tmp2,two,MPFR_RNDU);mpfr_add(tmp,tmp,tmp2,MPFR_RNDU);mpfr_mul(I1,eg,tmp,MPFR_RNDU);mpfr_add(T1,T1,I1,MPFR_RNDU);mpfr_clear(Dseg);mpfr_clear(g2);mpfr_clear(eg);}mpfr_clear(laU);}setd(E0,"0.0003",MPFR_RNDU);setd(E1,"0.004",MPFR_RNDU);setd(d,"0.501",MPFR_RNDU);mpfr_div(tmp,la,tb,MPFR_RNDD);mpfr_div(Phi,tmp,four,MPFR_RNDD);setd(tmp,"0.000001",MPFR_RNDU);mpfr_sub(Phi,Phi,tmp,MPFR_RNDD);mpfr_sub(S0,one,T0,MPFR_RNDD);mpfr_div(half,E0,two,MPFR_RNDU);mpfr_sqr(rad,S0,MPFR_RNDD);mpfr_sqr(tmp,half,MPFR_RNDU);mpfr_sub(rad,rad,tmp,MPFR_RNDD);int ok=mpfr_cmp(S0,half)>0&&mpfr_cmp_ui(rad,0)>0;if(ok){mpfr_sqrt(Y,rad,MPFR_RNDD);mpfr_mul(lhs,Phi,Y,MPFR_RNDD);mpfr_mul(tmp,d,T1,MPFR_RNDU);mpfr_sub(lhs,lhs,tmp,MPFR_RNDD);mpfr_mul(lhs,lhs,two,MPFR_RNDD);mpfr_sub(margin,lhs,E1,MPFR_RNDD);}else setd(margin,"-100",MPFR_RNDD);mpfr_set(A0,T0,MPFR_RNDU);mpfr_set(A1,T1,MPFR_RNDU);for(size_t i=0;i<sizeof(v)/sizeof(v[0]);i++)mpfr_clear(*v[i]);return ok;}
int main(){init_logs();mpfr_t minm,m,A0,A1;ini(minm);ini(m);ini(A0);ini(A1);setd(minm,"1000",MPFR_RNDN);int mini=-1,minj=-1,fail=0;double aa=0,bb=0;for(int i=ILO;i<IHI;i++)for(int j=0;j<20;j++){int ok=eval_box(i,j,m,A0,A1);if(!ok||mpfr_cmp_ui(m,0)<=0)fail++;if(mpfr_cmp(m,minm)<0){mpfr_set(minm,m,MPFR_RNDN);mini=i;minj=j;aa=mpfr_get_d(A0,MPFR_RNDU);bb=mpfr_get_d(A1,MPFR_RNDU);}}printf("PSC lambda [7.039,7.040] PREC=%d ibox=[%d,%d) boxes=%d fail=%d\n",PREC,ILO,IHI,(IHI-ILO)*20,fail);printf("minimum_margin_lower=%.17g\n",mpfr_get_d(minm,MPFR_RNDD));printf("worst_t=[%.9f,%.9f] lambda=[%.6f,%.6f]\n",tlo(mini),thi(mini),(140780+minj)/20000.,(140781+minj)/20000.);printf("A0_upper=%.17g A1_upper=%.17g\n",aa,bb);printf("GRID_RESULT pass=%d\n",fail==0);mpfr_clear(minm);mpfr_clear(m);mpfr_clear(A0);mpfr_clear(A1);clear_logs();return fail?1:0;}
